diff --git a/internal/server/routes_auth.go b/internal/server/routes_auth.go
new file mode 100644
index 0000000..197c62e
--- /dev/null
+++ b/internal/server/routes_auth.go
@@ -0,0 +1,266 @@
+package server
+
+import (
+	"crypto/rand"
+	"encoding/base64"
+	"encoding/json"
+	"errors"
+	"fmt"
+	"io"
+	"net/http"
+	"net/mail"
+	"strings"
+	"sync"
+	"time"
+
+	"golang.org/x/crypto/bcrypt"
+
+	"git.aisoftwarefactory.world/linkshort3/linkshort3/internal/store"
+)
+
+// The auth card's limits: a password of at least 10 characters, and at most
+// 10 sign-up or log-in attempts per minute per client address.
+const (
+	minPasswordLen   = 10
+	authAttemptLimit = 10
+	authAttemptWindow = time.Minute
+	// maxAuthBody is what a credential JSON may weigh; anything bigger is a
+	// request to be read no further than that.
+	maxAuthBody = 4 << 10
+	// sessionTTL is how long a login cookie lives.
+	sessionTTL = 30 * 24 * time.Hour
+)
+
+func init() {
+	addRoutes(func(s *Server) {
+		s.HandleFunc("POST /api/signup", s.signup)
+		s.HandleFunc("POST /api/login", s.login)
+		s.HandleFunc("POST /api/logout", s.logout)
+		s.HandleFunc("GET /api/me", s.me)
+	})
+}
+
+// userJSON is what an account looks like to the app: never the hash.
+type userJSON struct {
+	ID    int64  `json:"id"`
+	Email string `json:"email"`
+}
+
+func userOf(u *store.User) userJSON { return userJSON{ID: u.ID, Email: u.Email} }
+
+// signupRate is the in-memory map of recent attempts, keyed by client address
+// and shared by /api/signup and /api/login.
+type signupRate struct {
+	mu     sync.Mutex
+	last   map[string]time.Time
+	counts map[string]int
+}
+
+var authRate = &signupRate{last: map[string]time{}, counts: map[string]int{}}
+
+// allow reports whether an attempt now fits the window; it also forgets
+// addresses whose window has passed, so the map stays small.
+func (r *signupRate) allow(key string, now time.Time) bool {
+	r.mu.Lock()
+	defer r.mu.Unlock()
+	for addr, first := range r.last {
+		if now.Sub(first) >= authAttemptWindow {
+			delete(r.last, addr)
+			delete(r.counts, addr)
+		}
+	}
+	if n, ok := r.counts[key]; ok && n >= authAttemptLimit {
+		return false
+	}
+	if _, ok := r.last[key]; !ok {
+		r.last[key] = now
+	}
+	r.counts[key]++
+	return true
+}
+
+// reset drops an address's window; a successful login starts counting afresh.
+func (r *signupRate) reset(key string) {
+	r.mu.Lock()
+	defer r.mu.Unlock()
+	delete(r.last, key)
+	delete(r.counts, key)
+}
+
+// clientIP is the request's remote address without its port: what a proxy in
+// front of us would see too, since the app is reached over plain HTTP here.
+func clientIP(r *http.Request) string {
+	host := r.RemoteAddr
+	if i := strings.LastIndex(host, "]"); i >= 0 {
+		if j := strings.Index(host[i:], ":"); j >= 0 {
+			return host[:i+1]
+		}
+		return host
+	}
+	if i := strings.LastIndex(host, ":"); i >= 0 {
+		return host[:i]
+	}
+	return host
+}
+
+// credentials is a signup or login body.
+type credentials struct {
+	Email    string `json:"email"`
+	Password string `json:"password"`
+}
+
+// decodeCredentials reads the JSON body of a signup or login, answering 400
+// for anything that is not a well-formed pair of strings.
+func decodeCredentials(w http.ResponseWriter, r *http.Request) (*credentials, bool) {
+	body, err := io.ReadAll(io.LimitReader(r.Body, maxAuthBody))
+	if err != nil {
+		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "bad request"})
+		return nil, false
+	}
+	var creds credentials
+	if err := json.Unmarshal(body, &creds); err != nil {
+		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "bad request"})
+		return nil, false
+	}
+	return &creds, true
+}
+
+// validEmail accepts what net/mail names as a single address with a domain.
+func validEmail(email string) bool {
+	addr, err := mail.ParseAddress(email)
+	if err != nil || addr.Address != email {
+		return false
+	}
+	at := strings.LastIndex(email, "@")
+	if at <= 0 || at == len(email)-1 {
+		return false
+	}
+	domain := email[at+1:]
+	if !strings.Contains(domain, ".") {
+		return false
+	}
+	for _, label := range strings.Split(domain, ".") {
+		if label == "" {
+			return false
+		}
+	}
+	return true
+}
+
+func (s *Server) signup(w http.ResponseWriter, r *http.Request) {
+	if !authRate.allow(clientIP(r), time.Now()) {
+		writeError(w, http.StatusTooManyRequests)
+		return
+	}
+	creds, ok := decodeCredentials(w, r)
+	if !ok {
+		return
+	}
+	email := strings.ToLower(strings.TrimSpace(creds.Email))
+	if !validEmail(email) {
+		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid email"})
+		return
+	}
+	if len(creds.Password) < minPasswordLen {
+		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "password too short"})
+		return
+	}
+	hash, err := bcrypt.GenerateFromPassword([]byte(creds.Password), bcrypt.DefaultCost)
+	if err != nil {
+		writeError(w, http.StatusInternalServerError)
+		return
+	}
+	user := &store.User{Email: email, PasswordHash: string(hash), CreatedAt: time.Now().UTC()}
+	if err := s.store.CreateUser(r.Context(), user); err != nil {
+		if errors.Is(err, store.ErrDuplicate) {
+			writeError(w, http.StatusConflict)
+			return
+		}
+		writeError(w, http.StatusInternalServerError)
+		return
+	}
+	s.startSession(w, r, user.ID)
+}
+
+func (s *Server) login(w http.ResponseWriter, r *http.Request) {
+	key := clientIP(r)
+	if !authRate.allow(key, time.Now()) {
+		writeError(w, http.StatusTooManyRequests)
+		return
+	}
+	creds, ok := decodeCredentials(w, r)
+	if !ok {
+		return
+	}
+	email := strings.ToLower(strings.TrimSpace(creds.Email))
+	user, err := s.store.GetUserByEmail(r.Context(), email)
+	if err != nil {
+		if errors.Is(err, store.ErrNotFound) {
+			writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "invalid credentials"})
+			return
+		}
+		writeError(w, http.StatusInternalServerError)
+		return
+	}
+	if bcrypt.CompareHashAndPassword([]byte(user.PasswordHash), []byte(creds.Password)) != nil {
+		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "invalid credentials"})
+		return
+	}
+	authRate.reset(key)
+	s.startSession(w, r, user.ID)
+}
+
+// startSession issues the login cookie and answers the user's JSON.
+func (s *Server) startSession(w http.ResponseWriter, r *http.Request, userID int64) {
+	token, err := newSessionToken()
+	if err != nil {
+		writeError(w, http.StatusInternalServerError)
+		return
+	}
+	now := time.Now().UTC()
+	expires := now.Add(sessionTTL)
+	if err := s.store.CreateSession(r.Context(), &store.Session{Token: token, UserID: userID, ExpiresAt: expires}); err != nil {
+		writeError(w, http.StatusInternalServerError)
+		return
+	}
+	http.SetCookie(w, sessionCookie(token, expires, requestSecure(r)))
+	writeJSON(w, http.StatusOK, userOf(&store.User{ID: userID}))
+}
+
+
