args.newString:
var authRate = &signupRate{last: map[string]time.Time{}, counts: map[string]int{}}

// resetAuthRate empties the window; tests that count attempts call it so they
// do not share the map with whoever ran before them.
func resetAuthRate() {
	authRate.mu.Lock()
	defer authRate.mu.Unlock()
	authRate.last = map[string]time.Time{}
	authRate.counts = map[string]int{}
}

